namespace NexoAvance {
public static class ActionBuilder {
 const string Root="Assets/NexoAvance",Work="C:/Users/jose/Documents/Codex/2026-09-22/ho/",Mark=Work+"work/acciones/pending-final",Out=Work+"outputs/Acciones/";static double after;
 [Serializable]class Dimensions{public float height;}
 [Serializable]class Marker{public string path;public Vector2 offset;}
 [Serializable]class Markers{public Marker[] values;}
 [Serializable]class Muzzles{public Vector2[] values;}
 [InitializeOnLoadMethod]static void Boot(){after=EditorApplication.timeSinceStartup+8;EditorApplication.update+=Tick;}
 static void Tick(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.timeSinceStartup<after)return;try{if(File.Exists(Mark)){if(!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;File.Delete(Mark);Install();File.WriteAllText(Mark+".export","build");after=EditorApplication.timeSinceStartup+10;}else if(File.Exists(Mark+".export")){File.Delete(Mark+".export");EditorApplication.update-=Tick;Export();}}catch(Exception e){File.WriteAllText(Out+"error.txt",e.ToString());EditorApplication.update-=Tick;}}
 [MenuItem("NEXO/Integrar acciones y ciclos de carrera")]public static void Install(){
  Directory.CreateDirectory(Out+"Antes");File.WriteAllText(Out+"progreso.txt","Importación final v3");AssetDatabase.Refresh();
  foreach(string hero in new[]{"Asalto","Exploradora","Artillero","Ingeniera"})foreach(string folder in new[]{hero,"Poses/"+hero,"Extras/"+hero})ReadFrames(Root+"/Art/Acciones/"+folder,245,new Vector2(.5f,30f/560));
  foreach(string robot in new[]{"Soldado","Cazador","Artillero","Bombardero","Incinerador","Electrico"})foreach(string folder in new[]{"Robots","RobotPoses"}){string dir=Root+"/Art/Acciones/"+folder+"/"+robot;var profile=AssetDatabase.LoadAssetAtPath<RobotProfile>(Root+"/Profiles/Robots/"+robot+".asset");float h=JsonUtility.FromJson<Dimensions>(File.ReadAllText(dir+"/dimensions.json")).height;float ppu=h/profile.pose.bounds.size.y;ReadFrames(dir,ppu,new Vector2(.5f,(30-profile.pose.bounds.min.y*ppu)/560));}
  foreach(string folder in new[]{"Robots","RobotPoses"})ReadFrames(Root+"/Art/Acciones/"+folder+"/Calamar",429f/7.6f,new Vector2(.5f,30f/560));
  File.WriteAllText(Out+"progreso.txt","Asignación final v3");var roster=AssetDatabase.LoadAssetAtPath<HeroRoster>(Root+"/Resources/HeroRoster.asset");if(!File.Exists(Out+"Antes/HeroRoster.asset"))File.Copy(Root+"/Resources/HeroRoster.asset",Out+"Antes/HeroRoster.asset");
  foreach(var hero in roster.heroes){string dir=Root+"/Art/Acciones/"+hero.name;if(!File.Exists(dir+"/0.png"))continue;var frames=LoadFrames(dir);hero.animations.run=frames;hero.animations.shootRun=frames;hero.animations.runMuzzles=JsonUtility.FromJson<Muzzles>(File.ReadAllText(dir+"/muzzles.json")).values;}
  foreach(var hero in roster.heroes){var f=LoadFrames(Root+"/Art/Acciones/Poses/"+hero.name);if(f.Length==6){var a=hero.animations;a.jumpStart=new[]{f[0]};a.rise=new[]{f[1]};a.fall=new[]{f[2]};a.doubleJump=new[]{f[1]};a.land=new[]{f[0]};a.meleePrepare=new[]{f[3]};a.meleeImpact=new[]{f[4]};a.meleeRecover=new[]{f[5]};}
   var extra=LoadFrames(Root+"/Art/Acciones/Extras/"+hero.name);if(extra.Length==6){var a=hero.animations;a.idle=new[]{extra[0],extra[0],extra[1],extra[1]};a.shoot=new[]{extra[2]};a.grenade=new[]{extra[3]};a.hurt=new[]{extra[4]};a.death=new[]{extra[4],extra[5]};}
  }
  foreach(var hero in roster.heroes){string path=Root+"/Art/Acciones/"+hero.name+"/markers.json";if(File.Exists(path))hero.spriteMuzzles=JsonUtility.FromJson<Markers>(File.ReadAllText(path)).values.Select(m=>new SpriteMuzzle{sprite=AssetDatabase.LoadAssetAtPath<Sprite>(Root+"/Art/Acciones/"+m.path),offset=m.offset}).ToArray();}
  foreach(string name in new[]{"Soldado","Cazador","Artillero","Bombardero","Incinerador","Electrico"}){var profile=AssetDatabase.LoadAssetAtPath<RobotProfile>(Root+"/Profiles/Robots/"+name+".asset");string dir=Root+"/Art/Acciones/Robots/"+name;if(!File.Exists(dir+"/dimensions.json"))continue;float height=JsonUtility.FromJson<Dimensions>(File.ReadAllText(dir+"/dimensions.json")).height;float ppu=height/profile.pose.bounds.size.y;profile.run=LoadFrames(dir);profile.spriteMuzzles=MakeAnchors(dir,profile.run,ppu);if(name=="Electrico")profile.idle=profile.run;string actions=Root+"/Art/Acciones/RobotPoses/"+name;if(File.Exists(actions+"/dimensions.json")){float ah=JsonUtility.FromJson<Dimensions>(File.ReadAllText(actions+"/dimensions.json")).height;float ap=ah/profile.pose.bounds.size.y;var f=LoadFrames(actions);profile.spriteMuzzles=profile.spriteMuzzles.Concat(MakeAnchors(actions,f,ap)).ToArray();profile.prepare=new[]{f[0]};profile.shoot=new[]{f[1]};profile.recover=new[]{f[2]};profile.hurt=new[]{f[3]};profile.death=new[]{f[4],f[5]};}EditorUtility.SetDirty(profile);}
  foreach(var hero in roster.heroes)if(hero.animations.meleeImpact.Length==0||hero.animations.meleeImpact[0]==null||hero.animations.grenade.Length==0||hero.animations.grenade[0]==null)throw new Exception("Faltan clips en "+hero.name);EditorUtility.SetDirty(roster);AssetDatabase.SaveAssets();File.WriteAllText(Out+"progreso.txt","Recursos asignados v3");foreach(string name in new[]{"CallesBajoControl","FabricaAutomatizada","NucleoNexo"}){string path=Root+"/Scenes/"+name+".unity";if(!File.Exists(Out+"Antes/"+name+".unity"))File.Copy(path,Out+"Antes/"+name+".unity");var scene=EditorSceneManager.OpenScene(path);var player=UnityEngine.Object.FindAnyObjectByType<ResistancePlayer>();if(!player.GetComponent<PlayerActions>())player.gameObject.AddComponent<PlayerActions>();if(name=="CallesBajoControl"){var boss=UnityEngine.Object.FindAnyObjectByType<OctopusBoss>(FindObjectsInactive.Include);if(boss){var rig=boss.GetComponent<BossAnimationRig>();if(!rig)rig=boss.gameObject.AddComponent<BossAnimationRig>();rig.idle=LoadFrames(Root+"/Art/Acciones/Robots/Calamar");rig.framesPerSecond=5;var f=LoadFrames(Root+"/Art/Acciones/RobotPoses/Calamar");if(f.Length==6){rig.prepareCannon=new[]{f[0]};rig.fireCannon=new[]{f[1]};rig.prepareSweep=new[]{f[0]};rig.sweep=new[]{f[2]};rig.prepareMissile=new[]{f[4]};rig.fireMissile=new[]{f[4]};rig.defeat=new[]{f[5]};rig.prepareStrike=new[]{f[0]};rig.strike=new[]{f[3]};}}}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}EditorSceneManager.OpenScene(Root+"/Scenes/MenuPrincipal.unity");File.WriteAllText(Out+"integracion.txt","Acciones compartidas y ciclos disponibles integrados.");
 }
 static Sprite[] LoadFrames(string dir){return Enumerable.Range(0,6).Select(i=>AssetDatabase.LoadAssetAtPath<Sprite>(dir+"/"+i+".png")).ToArray();}
 static SpriteMuzzle[] MakeAnchors(string dir,Sprite[] frames,float ppu){var points=JsonUtility.FromJson<Muzzles>(File.ReadAllText(dir+"/muzzles-pixels.json")).values;return frames.Select((f,i)=>new SpriteMuzzle{sprite=f,offset=new Vector2(points[i].x/ppu,points[i].y/ppu-.85f)}).ToArray();}
 static Sprite[] ReadFrames(string dir,float ppu,Vector2 pivot){if(!File.Exists(dir+"/0.png"))return new Sprite[0];var frames=new Sprite[6];for(int i=0;i<6;i++){string path=dir+"/"+i+".png";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.Sprite;imp.spriteImportMode=SpriteImportMode.Single;imp.spritePixelsPerUnit=ppu;imp.filterMode=FilterMode.Point;imp.mipmapEnabled=false;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.alphaIsTransparency=true;var settings=new TextureImporterSettings();imp.ReadTextureSettings(settings);settings.spriteAlignment=(int)SpriteAlignment.Custom;settings.spritePivot=File.Exists(dir+"/pivots.json")?JsonUtility.FromJson<Muzzles>(File.ReadAllText(dir+"/pivots.json")).values[i]:pivot;settings.spriteMeshType=SpriteMeshType.FullRect;imp.SetTextureSettings(settings);imp.SaveAndReimport();frames[i]=AssetDatabase.LoadAssetAtPath<Sprite>(path);}return frames;}
 public static void FinalBuild(){Install();Export();}
 [MenuItem("NEXO/Compilar acciones")]public static void Export(){var r=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"MenuPrincipal","CallesBajoControl","FabricaAutomatizada","NucleoNexo"}.Select(s=>Root+"/Scenes/"+s+".unity").ToArray(),locationPathName=Out+"NEXO/NEXO.exe",target=BuildTarget.StandaloneWindows64,options=BuildOptions.Development});File.WriteAllText(Out+"compilacion.txt",r.summary.result.ToString());}
}
